let tabs=document.querySelectorAll(".clients-tab"),contents=document.querySelectorAll(".clients-content");tabs.forEach(t=>t.addEventListener("click",()=>{let e=t.getAttribute("data-tab");tabs.forEach(t=>t.classList.remove("clients-tab--active")),t.classList.add("clients-tab--active"),contents.forEach(t=>{console.log(t),t.classList.remove("clients-content--active"),t.getAttribute("data-content")===e&&t.classList.add("clients-content--active")})})),document.addEventListener("click",t=>{t=t.target.closest(".clients-questions-item");t&&t.classList.toggle("clients-questions-item--active")});